using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;
using FluentAssertions;
using Meridian.Contracts.SecurityMaster;
using Meridian.Storage.SecurityMaster;

namespace Meridian.Tests.SecurityMaster;

/// <summary>
/// One independently specified schedule corpus shared by read, schema and relational consumers.
/// Expected values and diagnostic paths are committed data, never generated by the parser under test.
/// </summary>
internal static class SecurityEconomicScheduleFixtureCorpus
{
    private static readonly Lazy<IReadOnlyList<SecurityEconomicScheduleFixture>> Fixtures = new(Load);

    internal static IReadOnlyList<SecurityEconomicScheduleFixture> All => Fixtures.Value;

    internal static SecurityEconomicScheduleFixture Get(string id) => All.Single(fixture => fixture.Id == id);

    internal static SecurityTermsProjectionDescriptor Descriptor(string assetClass)
        => SecurityTermsProjectionRegistry.Descriptors.Single(descriptor => descriptor.AssetClass == assetClass);

    internal static SecurityDetailDto Detail(SecurityProjectionRecord record)
        => new(record.SecurityId, record.AssetClass, record.Status, record.DisplayName, record.Currency,
            record.CommonTerms, record.AssetSpecificTerms, record.Identifiers, record.Aliases, record.Version,
            record.EffectiveFrom, record.EffectiveTo);

    internal static object Column(IReadOnlyList<PostgresSecurityMasterStore.SecurityTermsProjectionValue> row, string name)
        => row.Single(column => column.ColumnName == name).Value;

    private static IReadOnlyList<SecurityEconomicScheduleFixture> Load()
    {
        var directory = Path.Combine(AppContext.BaseDirectory, "fixtures", "security-master", "schedule-validation");
        if (!Directory.Exists(directory))
            throw new InvalidOperationException($"Shared schedule fixtures are missing: {directory}");

        var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
        var fixtures = Directory.GetFiles(directory, "*.json").Order(StringComparer.Ordinal)
            .SelectMany(path => JsonSerializer.Deserialize<SecurityEconomicScheduleFixture[]>(File.ReadAllText(path), options)
                ?? throw new InvalidOperationException($"Schedule corpus '{path}' is empty."))
            .ToArray();
        fixtures.Should().NotBeEmpty();
        fixtures.Select(fixture => fixture.Id).Should().OnlyHaveUniqueItems();
        return fixtures;
    }
}

internal sealed record SecurityEconomicScheduleExpectedValue(string Date, decimal Value)
{
    internal DateOnly ParsedDate => DateOnly.Parse(Date, CultureInfo.InvariantCulture);
}

internal sealed record SecurityEconomicScheduleExpectedDiagnostic(string Code, string Path);

internal sealed class SecurityEconomicScheduleFixture
{
    public string Id { get; init; } = "";
    public string AssetClass { get; init; } = "";
    public JsonElement AssetSpecificTerms { get; init; }
    public JsonElement CommonTerms { get; init; }
    public string FactorPresence { get; init; } = "Absent";
    public string PrincipalPresence { get; init; } = "Absent";
    public string StepPresence { get; init; } = "Absent";
    public IReadOnlyList<SecurityEconomicScheduleExpectedValue> Factors { get; init; } = [];
    public IReadOnlyList<SecurityEconomicScheduleExpectedValue> Principal { get; init; } = [];
    public IReadOnlyList<SecurityEconomicScheduleExpectedValue> Steps { get; init; } = [];
    public IReadOnlyList<SecurityEconomicScheduleExpectedDiagnostic> Diagnostics { get; init; } = [];

    internal bool IsValid => Diagnostics.Count == 0;
    internal bool HasCommonTerms => CommonTerms.ValueKind == JsonValueKind.Object && CommonTerms.EnumerateObject().Any();

    internal SecurityProjectionRecord Record(Guid? securityId = null, long version = 1)
    {
        // Supply unrelated required class terms so every consumer can concentrate on the same
        // schedule evidence. Do not seed a schedule: absence itself is one of the test assertions.
        var terms = AssetClass switch
        {
            "Bond" => JsonSerializer.SerializeToNode(new
            {
                maturity = "2035-12-31",
                issueDate = "2020-01-01",
                par = 100m,
                couponType = "Fixed",
                couponRate = 5m,
                paymentFrequency = "SemiAnnual",
                dayCount = "Thirty360",
                isCallable = false,
                subclass = "Corporate"
            })!.AsObject(),
            "DirectLoan" => JsonSerializer.SerializeToNode(new
            {
                borrower = "Schedule corpus borrower",
                maturity = "2035-12-31",
                principal = 100m,
                currentCouponRate = 5m,
                covenants = Array.Empty<object>()
            })!.AsObject(),
            "StructuredCredit" => JsonSerializer.SerializeToNode(new
            {
                tranche = "A-1",
                collateralType = "RMBS",
                originalFace = 100m,
                currentFactor = 1m,
                couponOrIndex = "5",
                maturity = "2035-12-31"
            })!.AsObject(),
            _ => throw new InvalidOperationException($"Unknown fixture asset class '{AssetClass}'.")
        };
        terms["schemaVersion"] = 1;
        terms["assetClassTermsVersion"] = SecurityAssetClassCatalog.GetTermsVersion(AssetClass);

        var id = securityId ?? Guid.NewGuid();
        var effectiveFrom = new DateTimeOffset(2020, 1, 1, 0, 0, 0, TimeSpan.Zero);
        var displayName = $"Schedule corpus {Id}";
        var identifier = new SecurityIdentifierDto(SecurityIdentifierKind.InternalCode, $"SCHEDULE-{id:N}", true, effectiveFrom);
        return new(id, AssetClass, SecurityStatusDto.Active, displayName, "USD",
            SecurityIdentifierKind.InternalCode.ToString(), identifier.Value,
            Overlay(JsonSerializer.SerializeToElement(new { displayName, currency = "USD" }), CommonTerms),
            Overlay(JsonSerializer.SerializeToElement(terms), AssetSpecificTerms),
            JsonSerializer.SerializeToElement(new { sourceSystem = "schedule-corpus", asOf = effectiveFrom, updatedBy = "schedule-corpus" }),
            version, effectiveFrom, null, [identifier], []);
    }

    private static JsonElement Overlay(JsonElement defaults, JsonElement supplied)
    {
        if (supplied.ValueKind != JsonValueKind.Object)
            return defaults.Clone();
        // Copy source properties directly. A JsonObject assignment would silently collapse exact
        // duplicate names before the shared parser or PostgreSQL admission could reject them.
        var suppliedNames = supplied.EnumerateObject().Select(property => property.Name)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        using var buffer = new MemoryStream();
        using (var writer = new Utf8JsonWriter(buffer))
        {
            writer.WriteStartObject();
            foreach (var property in defaults.EnumerateObject())
                if (!suppliedNames.Contains(property.Name))
                    property.WriteTo(writer);
            foreach (var property in supplied.EnumerateObject())
                property.WriteTo(writer);
            writer.WriteEndObject();
        }
        using var document = JsonDocument.Parse(buffer.ToArray());
        return document.RootElement.Clone();
    }

    internal void AssertDiagnostics(IEnumerable<SecurityScheduleDiagnostic> actual)
        => actual.Select(diagnostic => new SecurityEconomicScheduleExpectedDiagnostic(diagnostic.Code, diagnostic.Path))
            .Should().Equal(Diagnostics, Id);

    internal void AssertSchedules(SecurityEconomicScheduleValidation actual)
    {
        actual.IsValid.Should().Be(IsValid, Id);
        actual.FactorSchedule.Presence.ToString().Should().Be(FactorPresence, Id);
        actual.PrincipalSchedule.Presence.ToString().Should().Be(PrincipalPresence, Id);
        actual.StepCouponSchedule.Presence.ToString().Should().Be(StepPresence, Id);
        AssertDiagnostics(actual.Diagnostics);
        if (!IsValid)
        {
            AssertNoPartialRows(actual.FactorSchedule);
            AssertNoPartialRows(actual.PrincipalSchedule);
            AssertNoPartialRows(actual.StepCouponSchedule);
            return;
        }

        actual.FactorSchedule.IsPresent.Should().Be(FactorPresence != "Absent", Id);
        actual.PrincipalSchedule.IsPresent.Should().Be(PrincipalPresence != "Absent", Id);
        actual.StepCouponSchedule.IsPresent.Should().Be(StepPresence != "Absent", Id);
        actual.FactorSchedule.Entries.Should().Equal(Factors.Select(value => new StructuredFactorScheduleEntry(value.ParsedDate, value.Value)), Id);
        actual.PrincipalSchedule.Entries.Should().Equal(Principal.Select(value => new StructuredPrincipalScheduleEntry(value.ParsedDate, value.Value)), Id);
        actual.StepCouponSchedule.Entries.Should().Equal(Steps.Select(value => new StructuredStepCouponEntry(value.ParsedDate, value.Value)), Id);
    }

    private void AssertNoPartialRows<T>(SecurityScheduleParseResult<T> schedule)
    {
        if (schedule.IsValid)
            return;
        schedule.Entries.Should().BeEmpty("invalid calculation entries must not be consumed: {0}", Id);
        schedule.SourceEntries.Should().BeEmpty("invalid source entries must not reach a tolerant codec: {0}", Id);
    }

    internal void AssertTerms(StructuredCashFlowTerms actual)
    {
        actual.FactorSchedule.Should().Equal(Factors.Select(value => new StructuredFactorScheduleEntry(value.ParsedDate, value.Value)), Id);
        if (PrincipalPresence == "Absent")
            actual.PrincipalSchedule.Should().BeNull(Id);
        else
            actual.PrincipalSchedule.Should().Equal(Principal.Select(value => new StructuredPrincipalScheduleEntry(value.ParsedDate, value.Value)), Id);
        if (StepPresence == "Absent")
            actual.StepCouponSchedule.Should().BeNull(Id);
        else
            actual.StepCouponSchedule.Should().Equal(Steps.Select(value => new StructuredStepCouponEntry(value.ParsedDate, value.Value)), Id);
    }

    internal void AssertProjection(PostgresSecurityMasterStore.SecurityTermsProjectionPlan plan)
    {
        AssertSchedules(plan.Schedules);
        if (AssetClass == "StructuredCredit")
        {
            var rows = plan.ChildRows("structured_credit_factor_schedule_projection");
            rows.Select(row => (DateTime)SecurityEconomicScheduleFixtureCorpus.Column(row, "as_of_date"))
                .Should().Equal(Factors.Select(value => value.ParsedDate.ToDateTime(TimeOnly.MinValue)), Id);
            rows.Select(row => (decimal)SecurityEconomicScheduleFixtureCorpus.Column(row, "factor"))
                .Should().Equal(Factors.Select(value => value.Value), Id);
            rows.Select(row => (int)SecurityEconomicScheduleFixtureCorpus.Column(row, "ordinal"))
                .Should().Equal(Enumerable.Range(0, Factors.Count), Id);
        }
        else if (AssetClass == "DirectLoan")
        {
            var rows = plan.ChildRows("direct_loan_principal_schedule_projection");
            rows.Select(row => (DateTime)SecurityEconomicScheduleFixtureCorpus.Column(row, "payment_date"))
                .Should().Equal(Principal.Select(value => value.ParsedDate.ToDateTime(TimeOnly.MinValue)), Id);
            rows.Select(row => (decimal)SecurityEconomicScheduleFixtureCorpus.Column(row, "amount"))
                .Should().Equal(Principal.Select(value => value.Value), Id);
            rows.Select(row => (int)SecurityEconomicScheduleFixtureCorpus.Column(row, "ordinal"))
                .Should().Equal(Enumerable.Range(0, Principal.Count), Id);
        }
    }
}
